    ///   - studentId: Codice univoco che consente di individuare uno studente.
    ///   - academicYearEnrollmentId: Identificativo dell'anno d'iscrizione.
    ///   - order: consente di specificare un ordine per il recupero dei record. La sintassi è la seguente * +/- : specifica l'ordinamento (+ = ASC, - = DESC); se omesso viene utilizzato + * field : nome del campo da ordinare E' possibile indicare più campi separandoli da virgola (Es: +annoCorso,+adCod)
    public func getEnrollmentsForTaxes(
        studentId: Int64,
        academicYearEnrollmentId: Int64? = nil,
        order: String? = nil
    ) async throws -> [Esse3EnrollmentForTuition] {
        try await client.jsonList(
            RestRequest(
                method: .get,
                path: "/tasse-service-v1/parametri-iscrizioni-per-tasse/\(RestRequest.pathSegment(studentId))",
                query: [("aaIscrId", academicYearEnrollmentId), ("order", order)]
            ),
            roles: [.technicalUser, .student, .provisionalEnrolledStudent]
        )
    }

    /// - Parameters:
    ///   - studentId: Codice univoco che consente di individuare uno studente.
    ///   - academicYearId: Identificativo dell'anno accademico.
    ///   - referenceDate: Data di riferimento.
    public func getTrafficLightParameters(
        studentId: Int64,
        academicYearId: Int64? = nil,
        referenceDate: String? = nil
    ) async throws -> Esse3TrafficLight {
        try await client.json(
            RestRequest(
                method: .get,
                path: "/tasse-service-v1/semaforo/\(RestRequest.pathSegment(studentId))",
                query: [("aaId", academicYearId), ("dataRif", referenceDate)]
            ),
            roles: [.student, .technicalUser]
        )
    }

    /// Consente di aggiornare lo status di una transazione in Esse3.
    ///
    /// - Parameters:
    ///   - body: Oggetto che contiene i dati del pagamento.
    public func postNotifyStatus(
        body: Esse3SpgTransactionStatusData
    ) async throws -> Esse3MessageOutcomeResponse {
        try await client.json(
            RestRequest(
                method: .post,
                path: "/tasse-service-v1/spg/notifyStatus",
                body: body
            ),
            roles: [.technicalUser]
        )
    }
}
